export const DRAUGHT_STATS=['hp','attack','defence','sp_attack','sp_defence','speed'];
export const activeDraughts=unit=>(unit.trainingEffects||[]).filter(e=>DRAUGHT_STATS.includes(e.stat)&&Number.isInteger(e.remaining)&&e.remaining>0&&e.remaining<=5).slice(0,10);
export function draughtQuote(state,unit,stat,duration){const turns=Number(duration),stacks=unit?activeDraughts(unit).filter(e=>e.stat===stat).length:0,rate=2**stacks,cost=turns*rate;const reason=!unit||unit.hp<=0||unit.dead?'Choose a living partner.':!DRAUGHT_STATS.includes(stat)||!Number.isInteger(turns)||turns<1||turns>5?'Choose a stat and one to five battles.':unit.level>=200?'This partner has reached the level cap.':activeDraughts(unit).length>=10?'This partner already has ten active draughts.':(state.cybressa?.trialMarks||0)<cost?'Not enough Trial Marks.':null;return {ok:!reason,reason,cost,turns,rate,stacks,bonus:(stacks+1)*20};}
export function buyTrainingDraught(state,unit,stat,duration){const q=draughtQuote(state,unit,stat,duration);if(!q.ok)return false;state.cybressa.trialMarks-=q.cost;unit.trainingEffects=[...activeDraughts(unit),{stat,remaining:q.turns,durationUnit:'battles'}];return true;}
export function trainingGrowthBonus(unit,key){return activeDraughts(unit).filter(e=>e.stat===key).length*20;}
export function advanceTrainingEffects(unit){if(unit.trainingEffects)unit.trainingEffects=activeDraughts(unit).map(e=>({...e,durationUnit:'battles',remaining:e.remaining-1})).filter(e=>e.remaining>0);}
// A party battle consumes one use, after all its EXP, growth and evolution cards.
// Reserves do not consume uses unless they actually joined this battle.
export function trainingBattleUids(state,b){const ids=new Set([...(state.party||[]).map(u=>u.uid),...(b.participants||[]),b.alliedRivet?.uid].filter(Boolean));return [...(state.party||[]),...(state.reserve||[]),...(state.dead||[])].filter(u=>ids.has(u.uid)&&activeDraughts(u).length).map(u=>u.uid);}
export function settleTrainingBattle(state){const record=state.trainingBattleEnd;if(!record)return false;const ids=new Set(record.uids);for(const u of [...(state.party||[]),...(state.reserve||[]),...(state.dead||[])])if(ids.has(u.uid))advanceTrainingEffects(u);state.trainingBattleEnd=null;return true;}

